const truncate = (s: unknown, n = 60) => {
  const str = String(s ?? "");
  return str.length > n ? `${str.slice(0, n)}…` : str;
};

const badge = (text: string, cls: string) => (
  <span className={`text-[10px] font-bold uppercase px-2 py-0.5 rounded-full border ${cls}`}>{text}</span>
);

